insert into public.courses (slug, title, subject, credits, focus)
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 1, $j$1.1 Plot and Conflict$j$, $j${"body": "Read the short story \"The Gift of the Magi\" by O. Henry (public domain). Then read this lesson.\n\nPlot is the order of events in a story: exposition, rising action, climax, falling action and resolution. Conflict is the struggle that drives the plot. External conflict is a struggle against something outside the character. Internal conflict is a struggle inside the character.\n\nYour task: name the conflict in the story, mark the climax, and say whether the main conflict is external or internal.\n\nFlorida standards: ELA.9.R.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.1", "script": "Welcome to English 1. Every story you have ever loved is built on one simple idea: somebody wants something, and something stands in the way. That is the heart of plot.\n\nPlot is the order of events in a story, and it has a shape. First comes the exposition, where we meet the characters and learn the setting. Then comes the rising action, where trouble begins to build. Next is the climax, the turning point, the moment when everything changes. After that comes the falling action, and finally the resolution, where we see how things settle.\n\nWhat drives that shape is conflict. Conflict is the struggle at the center of the story, and there are two main kinds. External conflict is a struggle against something outside the character, such as another person, nature or society. Internal conflict is a struggle inside the character, such as fear against courage, or temptation against conscience.\n\nLet me give you an example from Scripture. In First Samuel chapter seventeen, David faces Goliath. The external conflict is easy to see: a shepherd boy against a giant. But there is an internal conflict too. David has to choose between fear and faith. Good readers learn to notice both kinds, because the internal struggle often tells us what the story is really about.\n\nHere is how to read for plot. As you read, ask three questions. First, what does the main character want? Second, what is in the way? Third, what changes at the turning point? If you can answer those three questions, you understand the plot.\n\nYour reading this week is \"The Gift of the Magi\" by O. Henry. As you read, mark the point where the problem first appears, and mark the climax. Write down whether the main conflict is inside the characters or outside of them. Then take the four question check below.\n\nRemember, you may retake any check as many times as you need. Learning is not about getting it right the first time. It is about staying with it until you understand. That is the kind of discipline that builds character. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 2, $j$1.2 Character and Characterization$j$, $j${"body": "Read \"The Gift of the Magi\" again, this time watching the characters.\n\nCharacterization is how an author shows us who a character is. Direct characterization tells us outright. Indirect characterization shows us through what the character says, does, thinks and how others react. A round character is complex and changes. A flat character stays simple. A dynamic character changes; a static character does not.\n\nYour task: choose one character and list three details that reveal who he or she is. Say whether each detail is direct or indirect.\n\nFlorida standards: ELA.9.R.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.1", "script": "In the last lesson we looked at plot. Today we look at the people who live inside it. A story can have a clever plot, but if we do not care about the characters, we stop reading.\n\nCharacterization is how an author shows us who a character is. There are two main ways. Direct characterization is when the narrator simply tells us: she was a generous woman, or he was a proud man. Indirect characterization is when the author shows us through the character's words, actions and thoughts, and through how other people treat that character.\n\nIndirect characterization asks the reader to do some work, and that is where reading becomes interesting. If a character gives up his lunch so a friend can eat, we do not need the narrator to say he is kind. His action tells us.\n\nNow let us learn some vocabulary for kinds of characters. A round character is complex, with strengths and weaknesses, and often feels like a real person. A flat character is simple and shows only one or two traits. A dynamic character changes over the course of the story. A static character stays the same from beginning to end.\n\nScripture gives us wonderful examples. Think of Peter. He speaks boldly, he acts quickly, he fails, he weeps, and he is restored. Peter is a round character, and he is dynamic, because he changes. The Gospels rarely say Peter is impulsive. They show us, through what he says and does.\n\nWhen you read, use this method. Pick a character. Write down what the character says, what the character does, what the character thinks and what others say about him or her. Then make one sentence that sums up the person. Back that sentence up with evidence from the text.\n\nYour task today is to choose one character from \"The Gift of the Magi\" and list three details that reveal who that person is. Label each one direct or indirect. Then take the four question check.\n\nTake your time, and read with care. Every detail an author chooses was chosen for a reason. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 3, $j$1.3 Setting and Mood$j$, $j${"body": "Read Genesis chapter 22, verses 1 to 14 in the King James Version, and notice the setting.\n\nSetting is the time and place of a story. Mood is the feeling the reader gets from it. Authors build mood through details of place, weather, sound and light. Setting can also shape the conflict.\n\nYour task: describe the setting of Genesis 22:1 to 14 in two sentences, and name the mood. Point to two words or details that create the mood.\n\nFlorida standards: ELA.9.R.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.1", "script": "Every story happens somewhere, and at some time. That is called the setting. Today we learn why setting matters, and how it makes us feel something before a single character speaks.\n\nSetting has two parts. The first is place: a city, a farm, a ship at sea or a mountain. The second is time: the year, the season or even the hour of the day. Good authors choose both on purpose.\n\nSetting does three jobs. First, it gives us a world to picture. Second, it can shape the conflict, because a storm at sea creates different problems than a quiet kitchen. Third, it creates mood.\n\nMood is the feeling the reader gets from the text. It is different from tone, which is the author's attitude. Mood is about you, the reader. Does the passage feel peaceful, tense, sad or hopeful? Authors build mood with details we can see, hear, smell and touch. Dark clouds, a silent road, a creaking door, a warm fire.\n\nLet us look at Genesis chapter twenty two. Abraham is told to take Isaac to a mountain in the land of Moriah. Notice what Scripture gives us: a journey of three days, wood laid on a son's shoulders, a mountain, a fire in the hand and a knife. Few words describe the scenery, yet the mood is heavy and tense. The simple details do the work. That is a lesson for writers too. You do not need many words to build a strong mood. You need the right ones.\n\nHere is how to read for setting. Ask what the time and place are. Underline the words that describe them. Then ask what mood those words create, and how that mood connects to what is happening.\n\nYour task today is to read Genesis twenty two, verses one through fourteen, in the King James Version. Write two sentences describing the setting, and name the mood. Point to two words or details that created that mood. Then take the four question check.\n\nRemember that when you write your own stories, setting is not decoration. It is part of the meaning. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 4, $j$1.4 Theme and Point of View$j$, $j${"body": "Read Luke chapter 15, verses 11 to 32, the parable of the prodigal son (King James Version).\n\nTheme is the central message about life that a story expresses. It is a full statement, not a single word. Point of view is who tells the story. First person uses \"I.\" Third person limited follows one character's thoughts. Third person omniscient knows every character's thoughts.\n\nYour task: state the theme of Luke 15:11 to 32 in one full sentence, and name the point of view.\n\nFlorida standards: ELA.9.R.1.2, ELA.9.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.2, ELA.9.R.1.3", "script": "We have studied plot, character and setting. Now we ask the biggest question about any story: what is it really about? That is theme. And we ask who is telling it, which is point of view.\n\nTheme is the central message or insight about life that a story expresses. It is not the topic. The topic might be forgiveness, but the theme is a full statement, such as: forgiveness restores what pride and selfishness have broken. A theme must be a complete sentence, and it must be supported by evidence from the text.\n\nHow do we find it? Follow these steps. First, notice what the main character wants at the start and what the character learns by the end. Second, look at how the conflict is resolved. Third, ask what the story seems to say about people or life. Then write your theme as a sentence and prove it with details.\n\nNow point of view. Point of view is the perspective from which the story is told. In first person, a character tells it with the word I, and we only know what that narrator knows. In third person limited, the narrator follows one character and shares only that character's thoughts. In third person omniscient, the narrator knows what every character thinks and feels.\n\nPoint of view changes how we understand a story. If the same event were told by a different person, we might judge it differently.\n\nLet us practice with the parable of the prodigal son in Luke chapter fifteen. A younger son leaves home, wastes his inheritance, and returns in shame. His father runs to meet him. The older brother is angry. The narrator is third person, and we can see inside several hearts, the father's compassion and the older brother's resentment. One possible theme is this: grace is offered freely, and pride can keep us from receiving it.\n\nYour task is to read Luke fifteen, verses eleven through thirty two, in the King James Version. Write one full sentence stating a theme, and name the point of view. Then take the four question check.\n\nA good theme is not a slogan. It is something you can show is true from the text. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 5, $j$2.1 How to Read a Poem$j$, $j${"body": "Read Psalm 1 (King James Version) and \"The Road Not Taken\" by Robert Frost (public domain).\n\nA poem is organized in lines and stanzas. A line is one row of words. A stanza is a group of lines, like a paragraph. The speaker is the voice in the poem, and may not be the poet. Read a poem three times: once for sound, once for meaning, once for craft.\n\nYour task: write down the speaker, the subject and the number of stanzas in the poem by Robert Frost.\n\nFlorida standards: ELA.9.R.1.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.4", "script": "Welcome to our unit on poetry. Some people feel nervous about poems. They think poetry is a puzzle with a secret answer. Today I want to take that fear away and give you a simple method.\n\nStart with the shape of a poem. A poem is written in lines, and the lines are grouped into stanzas. A stanza is like a paragraph of poetry. The way a poet breaks a line is a choice, and it often tells us what to emphasize.\n\nNext, find the speaker. The speaker is the voice that talks in the poem. The speaker is not always the poet. Just as a novel has a narrator, a poem has a speaker, and you should ask who is talking, to whom and why.\n\nNow the method. Read the poem three times. The first time, read it aloud for sound. Poetry was made to be heard. Notice the rhythm and the rhymes. The second time, read for meaning. Ask what is happening, and what the poem is about on the surface. The third time, read for craft. Ask what words, images and comparisons the poet chose, and what they add.\n\nLet us try it with the very first Psalm. It begins, Blessed is the man that walketh not in the counsel of the ungodly. In just a few verses, we find a picture: the righteous person is like a tree planted by rivers of water, and the ungodly are like chaff that the wind drives away. Notice that the Psalm does not argue. It paints two pictures and lets us compare them. That is how a poem can teach.\n\nNotice, too, the pattern. Hebrew poetry often uses parallelism, which means saying something in one line and then echoing or contrasting it in the next. Once you see it, you will find it throughout the Psalms and Proverbs.\n\nYour task today has two readings: Psalm one in the King James Version and \"The Road Not Taken\" by Robert Frost. For the Frost poem, write down the speaker, the subject and the number of stanzas. Then take the four question check.\n\nPoetry rewards patience. The more slowly you read, the more you will see. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 6, $j$2.2 Imagery and Sound$j$, $j${"body": "Read Psalm 19, verses 1 to 6 (King James Version).\n\nImagery is language that appeals to the senses: sight, sound, smell, taste, touch. Sound devices include rhyme, alliteration (repeated beginning sounds), assonance (repeated vowel sounds) and rhythm.\n\nYour task: find three images in Psalm 19:1 to 6 and name the sense each one appeals to.\n\nFlorida standards: ELA.9.R.1.4, ELA.9.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.4, ELA.9.R.3.1", "script": "A poem does not just tell you something. It lets you experience it. Today we study two tools that make that happen: imagery and sound.\n\nImagery is language that appeals to the five senses. When a poet writes about a cold, silver morning, you can see the color and almost feel the chill. Strong images are specific. Instead of saying a pretty flower, a poet might say a crimson rose heavy with rain.\n\nWhen you read a poem, underline the images, and label which sense each one reaches. Sight is the most common, but good poems also use sound, smell, taste and touch.\n\nNow the music of poetry. Poets use sound on purpose. Rhyme is the repetition of ending sounds, like light and night. Alliteration is the repetition of beginning consonant sounds, like silver, sweet, singing. Assonance is the repetition of vowel sounds inside words, like the long o in slow and cold. Rhythm is the beat created by stressed and unstressed syllables.\n\nThese devices are not decoration. They help create mood and meaning. Soft, flowing sounds may calm us, while sharp, short sounds may create tension.\n\nLet us hear this in Psalm nineteen. The heavens declare the glory of God; and the firmament sheweth his handywork. Day unto day uttereth speech, and night unto night sheweth knowledge. Notice the picture of the sky as a speaker who talks without words, and notice the balance in the lines, day unto day, night unto night. Later the sun is pictured as a bridegroom coming out of his chamber, and as a strong man ready to run a race. These are rich images, and they stretch our sense of how large and joyful creation is.\n\nHere is your method. Read the passage aloud. Mark every image and name the sense. Listen for repeated sounds. Then ask what feeling the images and sounds build together.\n\nYour task today is to read Psalm nineteen, verses one through six, in the King James Version. Find three images and tell which sense each appeals to. Then take the four question check.\n\nWhen you read slowly and aloud, poetry opens up in a way that silent reading never does. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 7, $j$2.3 Simile, Metaphor and Symbol$j$, $j${"body": "Read Psalm 23 (King James Version).\n\nFigurative language means words used beyond their plain meaning. A simile compares two things using like or as. A metaphor says one thing is another. A symbol is an object or image that stands for a larger idea. Personification gives human qualities to non human things.\n\nYour task: find one metaphor in Psalm 23 and explain what it means in your own words.\n\nFlorida standards: ELA.9.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.3.1", "script": "Poets and writers often say one thing and mean another, and they do it on purpose. This is called figurative language. Today we learn four of its most important tools.\n\nFigurative language uses words beyond their plain, literal meaning to create a deeper or more vivid idea. If I say, I am so hungry I could eat a horse, I do not mean it literally. I am using exaggeration to make a point.\n\nThe first tool is the simile. A simile compares two different things using the word like or as. Her smile was like sunshine. The second tool is the metaphor. A metaphor says one thing is another, without using like or as. Her smile was sunshine. Metaphors are bolder, because they ask us to see the two things as one.\n\nThe third tool is personification, which gives human qualities to something that is not human, as in, the wind whispered through the trees. The fourth tool is the symbol. A symbol is a person, place or object that stands for a larger idea. A dove can stand for peace, and a cross can stand for sacrifice and redemption.\n\nNow let us read the most famous metaphor in all of poetry. Psalm twenty three begins, The Lord is my shepherd; I shall not want. The poet does not say God is like a shepherd. He says God is a shepherd. That one metaphor opens a whole world: a shepherd leads, feeds, protects and stays near. Green pastures and still waters are images of provision and rest. The valley of the shadow of death is a hard place, yet the speaker says, I will fear no evil: for thou art with me. The rod and staff are symbols of protection and guidance.\n\nWhen you meet figurative language, use this method. First, name the device. Second, name the two things being compared. Third, ask what qualities pass from one to the other. Finally, say in your own words what the line means.\n\nYour task today is to read Psalm twenty three in the King James Version, find one metaphor, and explain its meaning in your own words. Then take the four question check.\n\nFigurative language gives writers a way to say what plain language cannot. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 8, $j$2.4 Reading Psalm 23 as Poetry$j$, $j${"body": "Read Psalm 23 again, and compare it with \"The Road Not Taken.\"\n\nPut your skills together. Identify the speaker, stanza or structure, images, sound devices and figurative language. Then state what the poem means as a whole.\n\nYour task: write a paragraph of 100 to 150 words explaining how two poetic devices help Psalm 23 comfort its reader.\n\nFlorida standards: ELA.9.R.1.4, ELA.9.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.1.4, ELA.9.R.3.1", "script": "Now we put it all together. You have learned about speaker, imagery, sound and figurative language. Today we read one poem slowly, using every tool, and watch how the pieces work as a whole.\n\nWe will use Psalm twenty three. It has only six verses, yet it has comforted people for thousands of years. Why? Let us read like writers.\n\nBegin with the speaker. The speaker is someone who trusts God personally. Notice the pronouns: my shepherd, my soul, my cup. This is not a distant poem. It is close and personal. Then, midway through the psalm, something shifts. In the first verses, the speaker talks about God, he maketh me to lie down. Then at the valley, the speaker begins talking to God, thou art with me. That change from he to thou is a movement from description to intimacy, and it happens at the moment of greatest danger. Readers who notice that shift see something the poem never explains out loud.\n\nNow look at the images. Green pastures and still waters are images of sight and calm. A table prepared in the presence of enemies is an image of honor in the middle of threat. The cup running over is an image of abundance.\n\nNext, the sound. The lines move in a steady, gentle rhythm. Many lines are balanced, with two parts that echo each other. That balance feels settled and calm, which matches the meaning.\n\nFinally, the figurative language. The whole psalm rests on one extended metaphor: God is the shepherd, and the speaker is the sheep. An extended metaphor is a comparison that continues through many lines.\n\nWhen you analyze a poem, do not stop at naming devices. Always connect them to meaning. Do not just say, there is a metaphor. Say, the shepherd metaphor shows that God guides and protects, and that is why the speaker does not fear.\n\nYour task today is to write one paragraph of one hundred to one hundred fifty words explaining how two poetic devices help Psalm twenty three comfort its reader. Name each device, give a quotation and explain its effect. Then take the four question check.\n\nA good reader does not only notice. A good reader explains why it matters. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 9, $j$3.1 Text Structure$j$, $j${"body": "Read the Gettysburg Address by Abraham Lincoln (public domain), about 270 words.\n\nInformational writing follows patterns called text structures: description, sequence, compare and contrast, cause and effect, and problem and solution. Signal words help you spot them, such as first, next, however, because, therefore.\n\nYour task: name the structure of the Gettysburg Address and list three signal words or phrases that helped you decide.\n\nFlorida standards: ELA.9.R.2.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.1", "script": "Today we begin reading informational text, which is writing that explains or argues, such as speeches, articles, essays and reports. The first skill is learning to see the structure underneath the words.\n\nWriters organize ideas in patterns, and when you recognize the pattern, the text becomes much easier to follow. There are five common patterns.\n\nThe first is description, where the writer paints a picture of a topic with details. The second is sequence, where events or steps come in order, using words such as first, then, next and finally. The third is compare and contrast, which shows how two things are alike and different, using words such as similarly, however and on the other hand. The fourth is cause and effect, which explains why something happened, using words such as because, as a result and therefore. The fifth is problem and solution, where the writer names a difficulty and proposes an answer.\n\nStructure matters because it reveals what the writer thinks is important. A writer who uses cause and effect wants you to understand why. A writer who uses problem and solution wants you to act.\n\nMany texts use more than one pattern. A speech may open with a description, move to a problem and end with a solution. Your job is to find the main structure and to notice the smaller ones inside it.\n\nHere is how to find structure. Skim the first sentence of each paragraph. Circle signal words. Then ask yourself, what question is this text answering? If it answers when, think sequence. If it answers why, think cause and effect. If it answers how are they alike, think compare and contrast.\n\nConsider the Gettysburg Address, which Abraham Lincoln delivered in 1863. He moves through time: four score and seven years ago, now we are engaged in a great civil war, and then, it is for us the living to be dedicated to the unfinished work. Past, present and future give the speech its shape. Inside that, he names a problem, whether a nation dedicated to liberty can endure, and he calls his listeners to a solution.\n\nYour task today is to read the Gettysburg Address, name its main structure, and list three signal words or phrases that helped you decide. Then take the four question check.\n\nWhen you can see the frame, you can understand the whole building. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 10, $j$3.2 Central Idea$j$, $j${"body": "Read Abraham Lincoln's Second Inaugural Address, the final paragraph beginning \"With malice toward none\" (public domain), and Ecclesiastes 3:1 to 8 (King James Version).\n\nThe central idea is the most important point a text makes about its topic. Supporting details are the facts, examples and reasons that develop it. The central idea is not the topic and not a small detail.\n\nYour task: write the central idea of Ecclesiastes 3:1 to 8 in one sentence, and list two supporting details.\n\nFlorida standards: ELA.9.R.2.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.2", "script": "Every informational text has a main point. We call it the central idea. Today we learn to find it, state it and prove it.\n\nThe central idea is the most important message the author wants you to understand about the topic. Notice the difference between a topic and a central idea. The topic might be time. The central idea is a statement about time, such as: there is an appropriate season for every purpose in life. A topic is a word or a phrase. A central idea is a full sentence with a claim.\n\nSupporting details are the facts, examples, reasons and quotations that explain or prove the central idea. If the central idea is the trunk of a tree, the supporting details are the branches.\n\nHow do you find the central idea? Use four steps. First, read the title and the first and last paragraphs, because authors often state or restate their main point there. Second, look for ideas that repeat. If an idea shows up again and again, it matters. Third, ask what all the details have in common. Fourth, test your sentence. Does every major detail support it? If a major detail does not fit, revise.\n\nLet us practice with Ecclesiastes chapter three. To every thing there is a season, and a time to every purpose under the heaven. Then comes a list: a time to be born and a time to die, a time to plant and a time to pluck up, a time to weep and a time to laugh. The topic is time. The repeated pattern gives us the clue. Every line pairs two opposite experiences, and each is given its own time. A fair statement of the central idea would be: life includes many different seasons, and each has its purpose in God's plan. The details, planting and plucking, weeping and laughing, serve as support.\n\nNotice that a central idea can be stated directly or only implied. In some texts the author tells you. In others, you infer it from the details. Either way, you must be able to point to evidence in the text.\n\nYour task today is to read the final paragraph of Lincoln's Second Inaugural Address and Ecclesiastes three, verses one through eight, in the King James Version. Write the central idea of Ecclesiastes in one sentence and list two supporting details. Then take the four question check.\n\nLook for the main point first. Everything else will make more sense. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 11, $j$3.3 Author's Purpose and Perspective$j$, $j${"body": "Read the first six paragraphs of Frederick Douglass, \"What to the Slave Is the Fourth of July?\" (public domain), or the excerpt your teacher assigns.\n\nAuthor's purpose is the reason an author writes: to inform, to persuade, to entertain or to express. Perspective is the author's point of view shaped by experience and beliefs. Word choice, tone and what the author includes or leaves out reveal both.\n\nYour task: state the purpose and perspective of the Douglass speech and give two pieces of evidence.\n\nFlorida standards: ELA.9.R.2.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.3", "script": "Why did the author write this? That question unlocks almost every text. Today we study author's purpose and perspective.\n\nAuthor's purpose is the reason a text was written. Authors usually write for one or more of four purposes: to inform, to persuade, to entertain or to express feelings and ideas. A news report mainly informs. An advertisement persuades. A story entertains. A personal poem expresses.\n\nPerspective is the author's point of view, shaped by experiences, beliefs, culture and goals. Two people can describe the same event very differently, because each sees it from where he or she stands.\n\nHow do you discover purpose and perspective? Look at four clues. First, word choice: strong, emotional words suggest persuasion; neutral words suggest information. Second, tone: is the author angry, hopeful, serious or humorous? Third, what is included and what is left out. Fourth, who the audience is and what the author wants the audience to do or understand.\n\nLet us consider a famous example. In 1852, Frederick Douglass was invited to speak in Rochester, New York, at an Independence Day celebration. Douglass had been born into slavery and escaped. His speech does not simply celebrate. He asks, What to the slave is the Fourth of July? His purpose is to persuade his audience that a nation proud of liberty cannot ignore slavery. His perspective comes from lived experience, which gives his words a weight no outside observer could match. Notice his tone moves from respectful, to serious, to burning. He uses questions and strong words to make his audience uncomfortable enough to think.\n\nNow notice how Douglass also draws on Scripture. He quotes the Psalms and the prophets to remind his hearers of their own faith. His purpose and his perspective work together.\n\nWhen you read, always ask these four questions. Who wrote this? What do they want me to do, think or feel? What evidence in the words shows that? And what might they be leaving out?\n\nYour task today is to read the opening paragraphs of the Douglass speech, state its purpose and perspective, and give two pieces of evidence from the text. Then take the four question check.\n\nGood readers do not only absorb a text. They ask why it was written. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 12, $j$3.4 Summarizing, Paraphrasing and Comparing$j$, $j${"body": "Read the Gettysburg Address and Lincoln's Second Inaugural Address final paragraph again.\n\nA summary is a short version of the main ideas in your own words. A paraphrase restates a passage in your own words at about the same length. Neither is a copy. To compare two texts, look at topic, purpose, structure, tone and central idea.\n\nYour task: write a 3 sentence summary of the Gettysburg Address, and one sentence telling how it differs from the Second Inaugural in tone.\n\nFlorida standards: ELA.9.R.3.2, ELA.9.R.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.3.2, ELA.9.R.3.3", "script": "You will read many things in school and in life, and you will need to explain them to others. Today we practice two important skills, summarizing and paraphrasing, and one more, comparing two texts.\n\nA summary is a short version of a text that tells the main ideas in your own words. A good summary leaves out small details and opinions. It answers who, what, when, where and why, and it states the central idea. A paraphrase is different. A paraphrase restates a specific passage in your own words, at about the same length, keeping all the meaning. You use paraphrase when you need to explain a hard sentence.\n\nBoth skills share a rule: use your own words. Copying the author's sentences is not summarizing. It is not even paraphrasing. If you use the author's exact words, put them in quotation marks and give credit.\n\nHere is a method for summarizing. First, read the whole text. Second, find the central idea. Third, list the key supporting points, in order. Fourth, write the summary from your list, without looking at the text. Last, check it for accuracy, and be sure it is much shorter than the original.\n\nFor example, Lincoln begins, Four score and seven years ago our fathers brought forth on this continent a new nation. A paraphrase might say: eighty seven years ago, our nation's founders created a new country. Notice that the meaning is the same, but the words are ours.\n\nNow comparing. When you compare two texts, look at the topic, the purpose, the structure, the tone and the central idea. Ask what is similar and what is different. Lincoln's Gettysburg Address is short and solemn, focused on honoring the fallen and renewing the nation's purpose. His Second Inaugural Address is longer, reflective and hopeful, and ends with a call for mercy: with malice toward none, with charity for all. Both speeches aim to heal a divided nation, yet their tone and length differ.\n\nYour task today is to write a three sentence summary of the Gettysburg Address, and one sentence telling how it differs in tone from the Second Inaugural Address. Then take the four question check.\n\nClear, honest summaries are a sign of understanding. If you can explain it simply, you truly know it. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 13, $j$4.1 What an Argument Is$j$, $j${"body": "Read Joshua 24:14 to 24 (King James Version), where Joshua urges Israel to choose whom they will serve.\n\nIn English class, an argument is not a fight. It is a claim supported by reasons and evidence. The parts are: a claim, reasons, evidence, a counterclaim and a rebuttal.\n\nYour task: identify Joshua's claim and two reasons he gives in Joshua 24.\n\nFlorida standards: ELA.9.R.2.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.4", "script": "When most people hear the word argument, they think of shouting. In English class, an argument means something far more useful. An argument is a claim supported by reasons and evidence, offered to persuade someone thoughtfully.\n\nAn argument has five parts. The first is the claim, which is the position you want people to accept. The second is the reasons, the points that explain why the claim is true. The third is the evidence, the facts, examples, statistics, quotations or expert opinions that back up each reason. The fourth is the counterclaim, which is what someone who disagrees might say. The fifth is the rebuttal, your response to the counterclaim.\n\nA strong argument is not just loud. It is fair, organized and supported. It treats the reader with respect, and it anticipates objections.\n\nIt is also important to separate fact from opinion. A fact can be checked and proven true or false. An opinion is a belief or judgment. Opinions are fine in arguments, but they need support from facts.\n\nLet us look at a classic argument in Scripture. In Joshua chapter twenty four, Joshua gathers the tribes of Israel and presents a choice. His claim is clear: Choose you this day whom ye will serve; but as for me and my house, we will serve the LORD. Notice what he does before he states it. He reminds them of the evidence: the God who brought their fathers out of Egypt, who protected them in the wilderness and who gave them the land. He also admits the other side. He names the gods of their fathers and of the Amorites, then asks them to choose. In this passage, he is not tricking anyone. He is laying out reasons and inviting a decision.\n\nHere is a simple way to test any argument. Ask four questions. What is the claim? What are the reasons? What evidence supports each reason? And has the author answered the other side?\n\nYour task today is to read Joshua twenty four, verses fourteen through twenty four, in the King James Version. Identify the claim and two reasons Joshua gives. Then take the four question check.\n\nLearning to argue well is learning to think well, and to speak the truth with respect. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 14, $j$4.2 Claims and Evidence$j$, $j${"body": "Read Proverbs 6:6 to 11 (King James Version) and think about the claim it makes.\n\nA strong claim is specific and debatable. Good evidence is relevant, accurate and enough. Types of evidence include facts, statistics, examples, expert testimony and quotations. Always explain how the evidence supports the claim. That explanation is called reasoning.\n\nYour task: write a claim about homework, sleep or reading, and support it with two reasons.\n\nFlorida standards: ELA.9.R.2.4, ELA.9.C.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.4, ELA.9.C.1.3", "script": "A claim without evidence is just an opinion. Today we learn how to write strong claims and support them well.\n\nStart with the claim. A strong claim has two qualities. First, it is specific. Schools are good is too broad. Schools should start the day later so students can learn better is specific. Second, it is debatable. A fact, such as the sky is blue, cannot be argued. A claim must be something a reasonable person could disagree with.\n\nNext comes evidence, which is the proof that supports your claim. There are several kinds. Facts and statistics give measurable information. Examples show the claim in real life. Expert testimony brings the voice of someone with knowledge. Quotations let the reader hear a source in its own words. Good evidence must be relevant, which means it connects to the claim. It must be accurate, which means it is true. And there must be enough of it.\n\nThen comes the step many students skip: reasoning. Reasoning is your explanation of how the evidence supports the claim. Do not just drop in a quotation and move on. After each piece of evidence, add a sentence beginning with this shows, this proves or this matters because.\n\nYou can use a simple pattern for each paragraph: claim, evidence, reasoning. Some teachers call it C E R.\n\nLet us see it in Scripture. In Proverbs chapter six, Solomon says, Go to the ant, thou sluggard; consider her ways, and be wise. The claim is that diligence leads to security and laziness leads to want. The evidence is the example of the ant, which has no guide, overseer or ruler, yet provides her food in the summer. The reasoning follows: if a tiny creature plans ahead without being told, then a person with understanding should do the same. And the closing warning shows the result of neglect: poverty comes as one that travelleth.\n\nNow you try. Choose a topic such as homework, sleep or reading. Write a specific, debatable claim. Give two reasons, and for each reason, name the kind of evidence you would use.\n\nYour task today is to complete that exercise, then take the four question check.\n\nStrong arguments are built one honest piece of evidence at a time. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 15, $j$4.3 Ethos, Pathos and Logos$j$, $j${"body": "Read Acts 26:1 to 29 (King James Version), Paul's defense before King Agrippa.\n\nRhetoric is the art of effective communication. Aristotle named three appeals: ethos (credibility), pathos (emotion) and logos (logic and evidence). Strong writers use all three, in balance.\n\nYour task: find one example of ethos, one of pathos and one of logos in Paul's speech to Agrippa.\n\nFlorida standards: ELA.9.R.3.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.3.4", "script": "Long before there were speeches on screens, ancient teachers studied what makes a speaker persuasive. The Greek thinker Aristotle named three tools that we still use today. They are ethos, pathos and logos.\n\nEthos is the appeal to credibility. It answers the question, why should I trust you? A speaker builds ethos by showing knowledge, experience, honesty and good character. When a doctor speaks about health, or a pastor speaks of long years of faithful service, we give them weight.\n\nPathos is the appeal to emotion. It answers the question, how should I feel? Stories, vivid images and personal examples can move the heart. Pathos is powerful, but it must be honest. Using emotion to trick people is manipulation.\n\nLogos is the appeal to logic and reason. It answers the question, does this make sense? Facts, statistics, clear reasoning and cause and effect build logos.\n\nThe best arguments balance all three. Too much emotion with no evidence feels empty. Too much logic with no heart feels cold. And a speaker with no credibility will not be heard.\n\nTogether, these tools belong to a larger subject called rhetoric, which is the art of using language effectively. Rhetoric also includes choices about word choice, repetition, rhetorical questions and tone.\n\nNow let us hear all three in the Book of Acts. In chapter twenty six, Paul stands before King Agrippa. He begins with courtesy: I think myself happy, king Agrippa, because I shall answer for myself this day before thee. He builds ethos by describing his background as a strict Pharisee. He uses pathos by telling his own story, how he once persecuted believers and then met the risen Christ on the road to Damascus. And he uses logos when he points to the prophets and Moses, saying he is speaking nothing but what they said would come. Then he asks, King Agrippa, believest thou the prophets? That rhetorical question puts the decision in the listener's hands.\n\nWhen you analyze a speech, label each appeal and explain its effect. Ask which one the speaker relies on most, and whether the balance works.\n\nYour task today is to read Acts twenty six, verses one through twenty nine, in the King James Version. Find one example each of ethos, pathos and logos. Then take the four question check.\n\nKnow the tools, and you will be harder to fool, and better at telling the truth well. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 16, $j$4.4 Reading Proverbs 15 as Wise Argument$j$, $j${"body": "Read Proverbs 15 (King James Version).\n\nProverbs often use contrast: the wise and the foolish, a soft answer and a harsh word. Many proverbs make a compact claim and rely on shared experience as evidence.\n\nYour task: choose one verse from Proverbs 15, state its claim in your own words, and explain which appeal (ethos, pathos or logos) is strongest.\n\nFlorida standards: ELA.9.R.2.4, ELA.9.R.3.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.R.2.4, ELA.9.R.3.4", "script": "We end our unit on argument with the book that may be the most compact collection of wisdom ever written. The Book of Proverbs packs claims, contrasts and evidence into single verses.\n\nLet us read Proverbs chapter fifteen with the tools we have learned. First, notice the structure. Many verses are built on contrast. A soft answer turneth away wrath: but grievous words stir up anger. The first half gives one path, the second half gives the other. Writers call this antithesis, and it is a powerful way to make a claim. By setting two outcomes side by side, the proverb lets the reader compare them quickly.\n\nSecond, notice the claim. Each proverb makes a claim, usually about how life works. A soft answer defuses conflict. A merry heart improves a person's whole outlook. Pride leads to a fall. These are specific, and a thoughtful person could test them against experience.\n\nThird, notice the evidence. Proverbs rarely list statistics, but they rely on shared human experience. Everyone has seen anger grow when harsh words are used. The evidence is life itself. In your own writing, you can borrow this approach by using examples your readers will recognize.\n\nFourth, notice the appeals. Proverbs build ethos by speaking as one with long wisdom. They use pathos by describing a merry heart and a broken spirit in ways we can feel. They use logos by showing cause and effect, if you do this, then that follows.\n\nFinally, think about the purpose. The author wants the reader to choose wisdom. That is a persuasive purpose, expressed with brevity and beauty.\n\nHere is how you can use this in your own writing. Try writing a proverb of your own. Make a claim in a short sentence, and use contrast. For example, patience builds trust, but haste breaks it. Then expand it into a short paragraph with an example and an explanation.\n\nYour task today is to read Proverbs fifteen in the King James Version. Choose one verse, state its claim in your own words, and explain which appeal is strongest. Then take the four question check and the Unit 4 quiz.\n\nWisdom is not only knowing what is right. It is learning to say it so that others can hear. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 17, $j$5.1 Planning and Thesis$j$, $j${"body": "Writing begins before the first sentence. Choose a topic, know your audience and purpose, gather ideas, and write a thesis statement.\n\nA thesis states your main point in one or two sentences. In an expository essay it explains. In an argumentative essay it takes a position.\n\nYour task: choose one topic from this list: the value of daily reading, the importance of integrity, or whether students should do community service. Write a thesis and a three point outline.\n\nFlorida standards: ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.1 (verify).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.1 (verify)", "script": "Many students make the same mistake. They start writing before they know what they want to say. Today we fix that by learning to plan, and to write a strong thesis.\n\nGood writing begins with three questions. What is my purpose? Who is my audience? What do I want to say? Your purpose might be to explain, which is expository writing, or to persuade, which is argumentative writing. Your audience might be a teacher, a classmate or the readers of a church newsletter. These choices shape your tone and your evidence.\n\nNext, gather ideas. Try brainstorming, where you list everything you can think of without judging. Try a web, with your topic in the middle and related ideas around it. Try freewriting for five minutes without stopping. Then circle the best ideas and discard the rest.\n\nNow comes the most important sentence in your essay: the thesis statement. A thesis states your main point in one or two sentences. It is not a fact, and it is not a question. In an expository essay it explains what you will teach. In an argumentative essay it takes a position that someone could disagree with.\n\nCompare these two. Weak: This essay is about reading. Strong: Reading for twenty minutes each day strengthens vocabulary, builds focus and prepares students for success in every subject. The strong thesis names a position and previews three supporting points.\n\nNext, build an outline. An outline is a roadmap. Your introduction ends with the thesis. Each body paragraph covers one point, with evidence. Your conclusion restates the thesis in fresh words and leaves the reader with something to think about.\n\nHere is a simple outline for a five paragraph essay. Paragraph one: hook, background, thesis. Paragraphs two, three and four: one point each, with evidence and reasoning. Paragraph five: conclusion.\n\nYour task today is to choose one topic from the list: the value of daily reading, the importance of integrity, or whether students should do community service. Write a thesis statement and a three point outline. Then take the four question check.\n\nPlanning feels slow, but it saves time. A good plan makes the writing flow. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 18, $j$5.2 Drafting Paragraphs$j$, $j${"body": "A strong body paragraph has a topic sentence, evidence, reasoning and a closing sentence. Transitions connect ideas.\n\nYour task: draft one body paragraph (6 to 8 sentences) for your outline from the last lesson. Use the pattern claim, evidence, reasoning.\n\nFlorida standards: ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.2 (verify).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.2 (verify)", "script": "Now that you have a plan, it is time to draft. Drafting means getting your ideas onto the page. The goal of a first draft is not perfection. The goal is progress.\n\nLet us build a strong body paragraph. Think of it as a small essay with its own parts. First, the topic sentence. This tells the reader the main idea of the paragraph, and it connects to your thesis. Second, evidence. This could be a fact, an example, a quotation or a statistic. Third, reasoning. This is where you explain how the evidence proves your point. Fourth, a closing sentence that wraps up the paragraph and, if needed, leads into the next one.\n\nAn easy way to remember is the pattern: claim, evidence, reasoning. Many writers add a concluding sentence and call it C E R C.\n\nNext, transitions. Transitions are words and phrases that connect ideas, so that your writing flows. For addition, use also, furthermore and in addition. For contrast, use however, but and on the other hand. For cause and effect, use because, therefore and as a result. For order, use first, next and finally. For example, use for instance and to illustrate.\n\nDo not forget the introduction. A good introduction has three parts. A hook grabs attention with a question, a surprising fact or a short story. Background gives the reader context. The thesis states your main point. And the conclusion should do three things as well: restate the thesis in fresh words, summarize your main points, and leave the reader with a final thought.\n\nHere is a sample body paragraph. Topic sentence: Daily reading strengthens vocabulary. Evidence: Studies show that students who read regularly encounter thousands of new words each year. Reasoning: Because readers meet words in context, they learn meanings naturally and remember them longer. Closing: In this way, reading does the work of a hundred vocabulary lists.\n\nAs you write, remember to keep your voice. Write clearly and honestly. Do not copy from other sources. If you use someone else's words or ideas, give credit.\n\nYour task today is to draft one body paragraph of six to eight sentences from your outline. Use claim, evidence, reasoning. Then take the four question check.\n\nDo not wait for the perfect sentence. Write, then improve. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 19, $j$5.3 Revising$j$, $j${"body": "Revising means improving ideas, organization and style. It is different from editing, which fixes grammar and spelling.\n\nRevision checklist: Is my thesis clear? Does each paragraph support it? Is there enough evidence and reasoning? Are my transitions smooth? Is my voice consistent?\n\nYour task: revise your paragraph from the last lesson using the checklist, and write one sentence telling what you changed.\n\nFlorida standards: ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.5 (verify).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.1.3, ELA.9.C.1.4, ELA.9.C.1.5 (verify)", "script": "Every good writer revises. In fact, writers often say that writing is rewriting. Today we learn how to revise with purpose.\n\nFirst, let us separate two steps that students often mix up. Revising is about big ideas: your thesis, your organization, your evidence and your style. Editing comes later, and it is about small things: grammar, spelling and punctuation. If you edit too early, you may polish a sentence that you later delete.\n\nHere is a revision checklist you can use on any essay. Number one, is my thesis clear and is it a position someone could debate? Number two, does every paragraph support the thesis? If a paragraph wanders, either connect it or cut it. Number three, do I have enough evidence, and have I explained it with reasoning? Number four, do my transitions help the reader move from one idea to the next? Number five, does my introduction pull the reader in and does my conclusion leave a lasting thought? Number six, is my voice clear, honest and consistent?\n\nThere are four powerful revision moves. Add, where you include more evidence or explanation. Cut, where you remove sentences that do not help. Move, where you rearrange ideas into a better order. Replace, where you swap vague words for specific ones. Instead of a good thing, say a lasting benefit. Instead of a lot of people, say hundreds of students.\n\nAnother tip: read your essay aloud. Your ears will catch awkward sentences and missing words that your eyes skip. Also, ask a trusted reader for feedback. Be humble when you receive it. Even the best writers have editors. Scripture says, in the multitude of counsellors there is safety. That applies to writing too.\n\nHere is a small example. Draft: Reading is good for you because it helps. Revised: Reading helps students build vocabulary, because every new book introduces words in context. Notice how the revised sentence is specific and gives a reason.\n\nYour task today is to take the paragraph you drafted, run it through the checklist, make at least three changes and write one sentence explaining what you changed and why. Then take the four question check.\n\nRevision is not a sign of failure. It is how good writing becomes great. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 20, $j$5.4 Editing and Publishing$j$, $j${"body": "Editing checks conventions: spelling, capitalization, punctuation, grammar and format. Publishing means preparing your final copy to share.\n\nEditing checklist: complete sentences, subject and verb agreement, capitalization, commas, apostrophes, quotation marks, spelling, and consistent tense.\n\nYour task: edit your revised paragraph, and write the final copy with a title.\n\nFlorida standards: ELA.9.C.1.5 (verify), ELA.9.C.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.1.5 (verify), ELA.9.C.3.1", "script": "You have planned, drafted and revised. Now you are ready for the last two stages of the writing process: editing and publishing.\n\nEditing is the careful check of conventions, the rules that make writing clear. Here is a checklist. First, complete sentences. Does every sentence have a subject and a verb and express a complete thought? Watch out for fragments and run on sentences. Second, subject and verb agreement. A singular subject takes a singular verb: the student reads. A plural subject takes a plural verb: the students read. Third, capitalization. Capitalize the first word of a sentence, proper nouns and the pronoun I. Fourth, punctuation. Use commas in a series, after introductory phrases and before conjunctions joining two independent clauses. Use apostrophes for possession and contractions. Use quotation marks around direct quotations. Fifth, spelling. Check commonly confused words such as their, there and they're, or its and it's. Sixth, consistent verb tense.\n\nHere are some editing strategies. Read your essay backward, sentence by sentence, so that you focus on form instead of meaning. Use a spell checker, but do not trust it fully, because it will not catch the wrong word spelled correctly. Read slowly with a ruler or finger so your eyes do not skip.\n\nKeep a personal error log. Write down the mistakes you make most often, and check for them every time. Over time, you will make fewer of them.\n\nThen comes publishing. Publishing means preparing your final copy to share. Add a title that tells the reader what to expect. Format your essay correctly, with clear paragraphs, one inch margins and a readable twelve point font. Include your name and date. If you used sources, list them.\n\nFinally, take a moment to celebrate your work. When you share your writing, you are not just completing an assignment. You are sharing a voice. As Colossians says, whatsoever ye do, do it heartily, as to the Lord. Do your best work.\n\nYour task today is to edit your revised paragraph using the checklist, then write your final copy with a title. Then take the four question check and the Unit 5 quiz.\n\nExcellent writing is patient writing. Take pride in your finish. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 21, $j$6.1 Context Clues$j$, $j${"body": "Context clues are hints in the surrounding words that help you figure out an unfamiliar word. Types: definition, synonym, antonym, example and inference.\n\nRead Proverbs 1:1 to 7 (King James Version) and look at words like prudence, subtilty and discretion.\n\nYour task: choose three unfamiliar words from this unit's readings and use context clues to define them, naming the clue type.\n\nFlorida standards: ELA.9.V.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.V.1.3", "script": "Every reader meets words they do not know. The good news is that you do not have to run to the dictionary every time. Today we learn to use context clues.\n\nContext means the words and sentences around the unfamiliar word. Authors often leave hints that help you figure out the meaning. There are five common types.\n\nThe first is a definition clue, where the author explains the word right there. For example, the sentence might say, a monarch, which is a king or queen, rules the land. The second is a synonym clue, where a word with a similar meaning appears nearby. The third is an antonym clue, where an opposite word appears, often after words like but or unlike. The fourth is an example clue, where the author gives examples that show the meaning. The fifth is an inference clue, where you work out the meaning from the overall situation.\n\nHere is a four step method. Step one, read the sentence and find the word. Step two, look around it for clues. Step three, make a guess about the meaning. Step four, test your guess by putting it in place of the word. Does the sentence still make sense? If so, you likely have it.\n\nLet us try it with Proverbs chapter one. To give subtilty to the simple, to the young man knowledge and discretion. The word subtilty in the King James Version means shrewdness or skill. The context tells us it is something given to the simple, so it is a quality that helps those who lack wisdom. And discretion, placed next to knowledge, means good judgment.\n\nBe careful, though. Many words have more than one meaning. Check that the meaning you choose fits the whole sentence. Also remember that older English, such as the King James Version, uses words that have changed in meaning. A good study Bible or a dictionary of older English can help.\n\nYour task today is to choose three unfamiliar words from this unit's readings, use context clues to define each one, and name the type of clue. Then take the four question check.\n\nA growing vocabulary is a growing mind. Read widely and read with curiosity. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 22, $j$6.2 Roots, Prefixes and Suffixes$j$, $j${"body": "Words are built from parts. A root carries the core meaning. A prefix comes before the root and changes its meaning. A suffix comes after and often changes the part of speech.\n\nExamples: pre (before), re (again), un (not), bene (good), dict (speak), port (carry), tion (act of).\n\nYour task: break down five words into prefix, root and suffix and give the meaning of each.\n\nFlorida standards: ELA.9.V.1.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.V.1.2", "script": "Here is a secret that can multiply your vocabulary. Many English words are built from smaller parts that you can learn. The study of word parts is called morphology.\n\nThree kinds of parts matter. A root carries the core meaning of the word. A prefix is added at the beginning and changes the meaning. A suffix is added at the end, and often changes the part of speech, for example from a verb to a noun.\n\nLet us look at some common prefixes. Un means not, as in unfaithful. Re means again, as in rebuild. Pre means before, as in prepare. Mis means wrong, as in misunderstand. Inter means between, as in interact. Sub means under, as in submarine.\n\nNow some useful roots, many from Latin and Greek. Dict means to speak, as in dictate and predict. Port means to carry, as in transport and portable. Scrib or script means to write, as in scribe and scripture. Bene means good, as in benefit. Spect means to look, as in inspect and spectator. Theo means God, as in theology. Bio means life, as in biology.\n\nCommon suffixes include tion and ment, which make nouns meaning act or state, as in education and agreement. Ful means full of, as in grateful. Less means without, as in hopeless. Able means can be done, as in readable. Ly often makes an adverb, as in quickly.\n\nLet us break down the word unforgiveness. The prefix un means not. The root forgive means to pardon. The suffix ness makes it a noun meaning a state. So unforgiveness is the state of not pardoning. Or take the word manuscript. Manu means hand, and script means write. A manuscript is something written by hand.\n\nHere is a tip. When you meet a new word, divide it into parts. Think of other words with the same parts. Then check the meaning against the context.\n\nYour task today is to break down five words into prefix, root and suffix and give the meaning of each part. Try these: benefactor, transport, prediction, rewrite and hopeless. Then take the four question check.\n\nWhen you know the parts, you can build your own understanding of thousands of words. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 23, $j$6.3 Connotation and Academic Vocabulary$j$, $j${"body": "Denotation is a word's dictionary meaning. Connotation is the feeling or association that comes with it. Words like slim, skinny and thin share a denotation but have different connotations.\n\nAcademic vocabulary includes words used in school and professional writing: analyze, evidence, infer, evaluate, interpret, summarize, compare, contrast.\n\nYour task: write three pairs of words with similar meanings but different connotations, and use each in a sentence.\n\nFlorida standards: ELA.9.V.1.1, ELA.9.V.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.V.1.1, ELA.9.V.1.3", "script": "Words carry more than their dictionary meanings. Today we study connotation, and we learn some of the important academic words you will see on tests and in college.\n\nEvery word has a denotation, which is its literal dictionary definition. Many words also have a connotation, which is the feeling or idea that comes along with the word. Take the words thin, slender and scrawny. All describe a lack of body weight, but slender sounds graceful, while scrawny sounds weak. The connotation can be positive, negative or neutral.\n\nAuthors choose connotations on purpose. A writer who calls someone stubborn is making a different point than a writer who calls the same person determined. Both describe someone who will not give up, but one sounds like a fault and the other a strength.\n\nConnotation matters in Scripture, too. Think of the difference between a servant and a slave in some translations, or between fear that means terror and fear that means reverence, as in the fear of the LORD is the beginning of knowledge. When reading, ask what feeling the word is adding.\n\nWhen you write, use connotation carefully. If you want your reader to feel respect, choose words with respectful connotations. If you describe something fairly, avoid loaded words that push the reader to a conclusion.\n\nNow academic vocabulary. These are words that appear again and again in school and professional writing. Analyze means to break something into parts to understand it. Evidence is information that supports a claim. Infer means to draw a conclusion from clues. Evaluate means to judge the quality or value of something. Interpret means to explain the meaning. Summarize means to give the main points briefly. Compare means to show how things are alike, and contrast means to show how they differ.\n\nWhen you see these words in test questions, you will know exactly what to do. If a question says analyze the author's argument, take it apart and explain how it works.\n\nTo make these words your own, use them. Write sentences, say them in conversation and look for them in your reading.\n\nYour task today is to write three pairs of words with similar meanings but different connotations, and use each in a sentence. Then take the four question check.\n\nChoose your words carefully. Words have power, and a good writer uses that power with care. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'topic', 24, $j$6.4 Clauses, Phrases, Colons and Semicolons$j$, $j${"body": "A phrase is a group of words without a subject and verb together. A clause has a subject and a verb. An independent clause stands alone; a dependent clause cannot.\n\nA semicolon joins two closely related independent clauses. A colon introduces a list, quotation or explanation after a complete sentence.\n\nYour task: write two sentences using a semicolon, two using a colon and one that uses a dependent clause correctly.\n\nFlorida standards: ELA.9.C.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.3.1", "script": "We end our course with two tools that make your sentences stronger and more varied. They are clauses and the punctuation that joins them.\n\nLet us begin with definitions. A phrase is a group of related words that does not have both a subject and a verb. Examples are in the morning, running down the hall and to the store. A clause is a group of words that has both a subject and a verb. There are two types. An independent clause can stand alone as a complete sentence: the students studied. A dependent clause has a subject and a verb but cannot stand alone, because it begins with a word like because, although, when or if. Although the students studied is not a complete sentence. It leaves us waiting.\n\nWhen you attach a dependent clause to an independent clause, you create a complex sentence. Although the students studied, they felt nervous. Note the comma after an introductory dependent clause.\n\nNow the semicolon. A semicolon joins two independent clauses that are closely related in meaning, without a conjunction. The students studied hard; they passed the test. Each side could be a sentence alone, but the semicolon shows a close connection. Also use a semicolon before a conjunctive adverb such as however or therefore: she was tired; however, she kept working.\n\nThen the colon. A colon follows a complete sentence and introduces a list, a quotation or an explanation. For example: Bring three things: a pencil, a notebook and a Bible. Or: He learned one lesson: patience pays. Do not put a colon directly after a verb or a preposition. Write, I need pencils, paper and a ruler, with no colon before the list.\n\nAlso notice the use of the colon in a quotation. In Philippians chapter four, we read: I can do all things through Christ which strengtheneth me.\n\nHere is a quick memory trick. A semicolon is like a soft period: it connects two complete thoughts. A colon is like a door: it opens to what comes next.\n\nYour task today is to write two sentences with semicolons, two with colons and one with a dependent clause used correctly. Then take the four question check and the Unit 6 quiz.\n\nStrong conventions free your ideas to be heard. Finish well. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 1, $j$Assessment 1: Literary Analysis Paragraph$j$, $j${"prompt": "Choose \"The Gift of the Magi\" or Luke 15:11 to 32 (KJV). Write one paragraph of 150 to 200 words. State a theme in one sentence. Support it with two pieces of evidence from the text, one about a character and one about the conflict. Name the point of view.", "rubric": "Total 100. Theme is a full statement: 25. Two pieces of text evidence: 30. Explains how the evidence supports the theme: 25. Clear writing and correct conventions: 20."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 2, $j$Assessment 2: Poetry Analysis$j$, $j${"prompt": "Choose Psalm 1, Psalm 19 or \"The Road Not Taken.\" Write 150 to 200 words explaining the meaning of the poem and how two devices (imagery, sound, simile, metaphor or symbol) help create that meaning. Use at least two quotations.", "rubric": "Total 100. States the meaning of the poem: 25. Names and explains two devices: 30. Uses two quotations correctly: 20. Connects devices to meaning: 15. Clear writing and conventions: 10."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 3, $j$Assessment 3: Summary and Purpose Response$j$, $j${"prompt": "Choose the Gettysburg Address or the Douglass speech. In 150 to 200 words, write (1) a three sentence summary in your own words, (2) the author's purpose and perspective, and (3) two pieces of evidence from the text.", "rubric": "Total 100. Accurate summary in own words: 30. States purpose and perspective: 25. Two pieces of evidence: 25. Clear writing and conventions: 20."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 4, $j$Assessment 4: Rhetorical Analysis$j$, $j${"prompt": "Choose Acts 26:1 to 29 or Proverbs 15 (KJV). In 175 to 225 words, state the claim, identify one example of ethos, pathos and logos (or the strongest two for Proverbs), and explain how each helps persuade.", "rubric": "Total 100. Accurate claim: 20. Three appeals identified correctly: 30. Explains the effect of each: 30. Clear writing and conventions: 20."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 5, $j$Assessment 5: Expository Essay$j$, $j${"prompt": "Write an expository essay of 400 to 500 words on one of these topics: the value of daily reading, the importance of integrity, or the benefits of community service. Include an introduction with a thesis, three body paragraphs and a conclusion.", "rubric": "Total 100. Clear thesis: 15. Organization and transitions: 20. Evidence and reasoning: 25. Style and word choice: 15. Conventions: 15. Length and format: 10."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 6, $j$Assessment 6: Vocabulary and Conventions in Use$j$, $j${"prompt": "Write a paragraph of 120 to 160 words about a lesson you learned this year. Include: two words with prefixes or suffixes that you explain, one word chosen for its connotation (explain why), one sentence with a semicolon, one with a colon, and one with a dependent clause. Label each in parentheses after the paragraph.", "rubric": "Total 100. Two word parts explained: 20. Connotation explained: 15. Semicolon, colon and dependent clause correct: 30. Clear paragraph: 20. Conventions: 15."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'assessment', 7, $j$Final Assessment: Argumentative Essay (500 words or more)$j$, $j${"prompt": "Write an argumentative essay of at least 500 words on this question: Should every student be required to read for twenty minutes every day? Take a clear position. Include an introduction with a hook and thesis, at least three body paragraphs with evidence and reasoning, a counterclaim with a rebuttal, and a conclusion. Use at least one quotation from Scripture (KJV) or from a text read in this course, and use ethos, pathos and logos on purpose.", "rubric": "Total 100. Clear, debatable thesis: 10. Organization and transitions: 15. Evidence from at least two sources and reasoning: 25. Counterclaim and rebuttal: 15. Use of rhetorical appeals: 10. Style and word choice: 10. Conventions: 10. Length of 500 words or more: 5. A score of 70 or better is required to pass. A certified proctor and the 500 word essay requirement apply to Test Out students."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 1, $j$Discussion 1: Choices That Reveal Character$j$, $j${"prompt": "Think of a character, in a book or in Scripture, whose choice revealed what he or she valued most. Describe the choice, and tell what it shows about the character. Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 2, $j$Discussion 2: A Picture That Stays With You$j$, $j${"prompt": "Share a line from a poem or Psalm that creates a picture in your mind. Tell what you see and what feeling it gives you. Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 3, $j$Discussion 3: Words That Move People$j$, $j${"prompt": "Tell about a speech, sermon or article that changed how you think. What was the author's purpose, and what did the author do to reach you? Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 4, $j$Discussion 4: Disagreeing Well$j$, $j${"prompt": "Think about a time you disagreed with someone and handled it well, or wish you had. What would a soft answer have changed? Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 5, $j$Discussion 5: My Writing Process$j$, $j${"prompt": "Which stage of writing is hardest for you: planning, drafting, revising or editing? Tell why, and share one strategy from this unit that you will try. Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'discussion', 6, $j$Discussion 6: A Word I Want to Own$j$, $j${"prompt": "Pick one new word you learned in this course. Tell where you found it, what it means and a sentence that uses it. Respond in 100 to 150 words."}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 1, $j$Check 1.1: Plot and Conflict$j$, $j${"questions": [{"q": "Which part of the plot is the turning point where everything changes?", "options": ["Resolution", "Exposition", "Climax", "Setting"]}, {"q": "A character fights fear inside himself before making a choice. This is an example of:", "options": ["Internal conflict", "Resolution", "Exposition", "External conflict"]}, {"q": "Which part of the plot introduces the characters and setting?", "options": ["Climax", "Falling action", "Resolution", "Exposition"]}, {"q": "David against Goliath is an example of which conflict?", "options": ["Only a resolution", "Neither", "External, and also internal because David must choose faith over fear", "Only internal"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 2, $j$Check 1.2: Character and Characterization$j$, $j${"questions": [{"q": "An author shows a character is kind by describing him giving away his coat. This is:", "options": ["Direct characterization", "Climax", "Indirect characterization", "Exposition"]}, {"q": "A character who changes during the story is called:", "options": ["Static", "Minor", "Dynamic", "Flat"]}, {"q": "A narrator says, 'Maria was a patient girl.' This is:", "options": ["A metaphor", "Direct characterization", "A theme", "Indirect characterization"]}, {"q": "A complex character with strengths and weaknesses is a:", "options": ["Minor plot", "Round character", "Static setting", "Flat character"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 3, $j$Check 1.3: Setting and Mood$j$, $j${"questions": [{"q": "Setting includes:", "options": ["Only the place", "The theme", "Both time and place", "Only the time"]}, {"q": "Mood is best described as:", "options": ["The author's opinion", "The main character's name", "The feeling the reader gets", "The plot's climax"]}, {"q": "Which detail most helps create a tense mood?", "options": ["A bright classroom", "A silent road at midnight", "A sunny picnic", "A cheerful song"]}, {"q": "How can setting affect conflict?", "options": ["It cannot", "It only changes the title", "It decides the theme alone", "A storm at sea creates different problems than a quiet kitchen"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 4, $j$Check 1.4: Theme and Point of View$j$, $j${"questions": [{"q": "Which is written as a theme?", "options": ["Forgiveness", "Pride can keep us from receiving grace", "Luke fifteen", "The prodigal son"]}, {"q": "A narrator who says 'I' is using:", "options": ["First person", "Third person omniscient", "Third person limited", "Second person"]}, {"q": "A narrator who knows every character's thoughts is:", "options": ["Third person omniscient", "Third person limited", "Static", "First person"]}, {"q": "To prove a theme you should:", "options": ["Guess", "Ignore the ending", "Copy the title", "Use details from the text as evidence"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 5, $j$Unit Quiz 1: Reading Fiction, Story Elements$j$, $j${"questions": [{"q": "The struggle that drives a plot is called:", "options": ["Conflict", "Diction", "Setting", "Mood"]}, {"q": "Which sequence is in the correct order?", "options": ["Exposition, rising action, climax, falling action, resolution", "Climax, exposition, resolution", "Resolution, climax, exposition", "Rising action, exposition, resolution"]}, {"q": "Telling the reader a character is brave is:", "options": ["Indirect characterization", "Direct characterization", "Setting", "Theme"]}, {"q": "A static character:", "options": ["Changes greatly", "Is always the hero", "Narrates", "Stays the same"]}, {"q": "Mood is:", "options": ["The ending", "The author's attitude", "The point of view", "The feeling the reader gets"]}, {"q": "A good theme is:", "options": ["The title", "One word", "A full statement about life supported by evidence", "The setting"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 6, $j$Check 2.1: How to Read a Poem$j$, $j${"questions": [{"q": "A group of lines in a poem is called a:", "options": ["Stanza", "Plot", "Scene", "Chapter"]}, {"q": "The voice that talks in a poem is the:", "options": ["Speaker", "Author's agent", "Reader", "Setting"]}, {"q": "The first reading of a poem should focus on:", "options": ["Sound, reading aloud", "Grammar mistakes", "The poet's biography", "Memorizing"]}, {"q": "Saying something in one line and echoing it in the next is called:", "options": ["Parallelism", "Dialogue", "Exposition", "Footnote"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 7, $j$Check 2.2: Imagery and Sound$j$, $j${"questions": [{"q": "Imagery appeals to:", "options": ["Only rhythm", "The senses", "Only grammar", "Only rhyme"]}, {"q": "Repetition of beginning consonant sounds is:", "options": ["Rhyme", "Alliteration", "Plot", "Assonance"]}, {"q": "The words 'light' and 'night' show:", "options": ["Rhyme", "Theme", "Setting", "Metaphor"]}, {"q": "Which is the strongest image?", "options": ["A crimson rose heavy with rain", "A thing", "A nice day", "Something good"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 8, $j$Check 2.3: Simile, Metaphor and Symbol$j$, $j${"questions": [{"q": "A comparison using 'like' or 'as' is a:", "options": ["Symbol", "Metaphor", "Simile", "Theme"]}, {"q": "'The Lord is my shepherd' is a:", "options": ["Metaphor", "Simile", "Exposition", "Alliteration"]}, {"q": "Giving human qualities to a non human thing is:", "options": ["Rhyme", "Irony", "Symbolism", "Personification"]}, {"q": "A dove standing for peace is a:", "options": ["Plot", "Stanza", "Symbol", "Pronoun"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 9, $j$Check 2.4: Reading Psalm 23 as Poetry$j$, $j${"questions": [{"q": "A comparison that continues through many lines is an:", "options": ["Extended metaphor", "Climax", "Alliteration", "Exposition"]}, {"q": "A strong analysis should:", "options": ["Retell the story", "Only list devices", "Avoid quotations", "Connect devices to meaning"]}, {"q": "The shift from 'he' to 'thou' in Psalm 23 shows:", "options": ["A move from description to closeness", "A mistake", "A rhyme scheme", "A change of setting"]}, {"q": "A table prepared in the presence of enemies is an image of:", "options": ["Travel", "Loneliness", "Honor in the middle of threat", "Hunger"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 10, $j$Unit Quiz 2: Poetry and Figurative Language$j$, $j${"questions": [{"q": "A group of lines in a poem is a:", "options": ["Stanza", "Thesis", "Scene", "Verse chapter only"]}, {"q": "Language that appeals to the senses is:", "options": ["Plot", "Thesis", "Imagery", "Syntax"]}, {"q": "'Her laugh was music' is a:", "options": ["Personification", "Metaphor", "Simile", "Alliteration"]}, {"q": "'Silver, sweet, singing' shows:", "options": ["Symbol", "Plot", "Rhyme", "Alliteration"]}, {"q": "'The wind whispered' is:", "options": ["Personification", "Setting", "Symbol", "Simile"]}, {"q": "Good poetry analysis connects devices to:", "options": ["Page numbers", "Rhyme only", "Meaning and effect", "The poet's age"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 11, $j$Check 3.1: Text Structure$j$, $j${"questions": [{"q": "Which structure uses words like 'because' and 'as a result'?", "options": ["Poetry", "Cause and effect", "Sequence", "Description"]}, {"q": "'First, next, finally' signal:", "options": ["Problem and solution", "Theme", "Sequence", "Compare and contrast"]}, {"q": "'However' and 'on the other hand' signal:", "options": ["Compare and contrast", "Sequence", "Cause only", "Description"]}, {"q": "To find structure, you might:", "options": ["Count the pages", "Skim the first sentence of each paragraph", "Memorize it", "Skip the text"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 12, $j$Check 3.2: Central Idea$j$, $j${"questions": [{"q": "A central idea is:", "options": ["A single word", "The title only", "A detail", "A full statement of the main point"]}, {"q": "Supporting details:", "options": ["Are always opinions", "Appear only in titles", "Replace it", "Explain or prove the central idea"]}, {"q": "Which is a topic, not a central idea?", "options": ["Seasons matter to God's plan", "People need patience in hard times", "Life has seasons, each with a purpose", "Time"]}, {"q": "A good test of a central idea is:", "options": ["Is it rhymed?", "Is it long?", "Do the major details support it?", "Is it the first line?"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 13, $j$Check 3.3: Author's Purpose and Perspective$j$, $j${"questions": [{"q": "An advertisement mainly has the purpose to:", "options": ["Entertain only", "Persuade", "Inform only", "Rhyme"]}, {"q": "Perspective is shaped by:", "options": ["The publisher only", "The author's experiences and beliefs", "The font", "The page count"]}, {"q": "Strong emotional word choice often signals:", "options": ["Persuasion", "A date", "A recipe", "A table of contents"]}, {"q": "Douglass asked, 'What to the slave is the Fourth of July?' to:", "options": ["Give directions", "Entertain", "Persuade the audience to face the truth about slavery", "Describe weather"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 14, $j$Check 3.4: Summarizing, Paraphrasing and Comparing$j$, $j${"questions": [{"q": "A summary should be:", "options": ["Full of opinions", "Longer than the original", "Short, in your own words, with the main ideas", "A copy of the first paragraph"]}, {"q": "A paraphrase is:", "options": ["A quotation", "A shorter list", "A restatement in your own words at about the same length", "A rhyme"]}, {"q": "If you use an author's exact words you should:", "options": ["Remove the title", "Change one word", "Say nothing", "Use quotation marks and give credit"]}, {"q": "When comparing texts, you might look at:", "options": ["Only the length of the title", "The color of the cover", "Purpose, tone, structure and central idea", "Page numbers"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 15, $j$Unit Quiz 3: Reading Informational Text$j$, $j${"questions": [{"q": "A text that explains why something happened uses:", "options": ["Sequence", "Cause and effect", "Description", "Poetry"]}, {"q": "The central idea is:", "options": ["A small detail", "The title only", "The main point as a full statement", "One word"]}, {"q": "Which is NOT a main purpose for writing?", "options": ["To persuade", "To entertain", "To inform", "To confuse on purpose"]}, {"q": "A summary uses:", "options": ["The author's exact sentences", "Only questions", "Only quotations", "Your own words"]}, {"q": "Author's perspective is shaped by:", "options": ["The font", "The index", "Experience and belief", "The price"]}, {"q": "Signal words like 'therefore' help you find:", "options": ["A metaphor", "Rhyme", "Setting", "Cause and effect"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 16, $j$Check 4.1: What an Argument Is$j$, $j${"questions": [{"q": "In English class an argument is:", "options": ["A story", "A claim supported by reasons and evidence", "A rhyme", "A shouting match"]}, {"q": "A counterclaim is:", "options": ["What someone who disagrees might say", "The conclusion", "A fact", "A title"]}, {"q": "A rebuttal is:", "options": ["A quotation", "A claim", "A response to a counterclaim", "A date"]}, {"q": "A fact is:", "options": ["Something that can be checked", "A belief", "A feeling", "A guess"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 17, $j$Check 4.2: Claims and Evidence$j$, $j${"questions": [{"q": "Which claim is strongest?", "options": ["Schools should start later so students sleep more and learn better", "The sky is blue", "I like lunch", "School is good"]}, {"q": "Reasoning is:", "options": ["Quoting twice", "Adding a title", "Explaining how the evidence supports the claim", "Skipping evidence"]}, {"q": "Evidence should be:", "options": ["Loud", "Long", "Funny", "Relevant, accurate and sufficient"]}, {"q": "In Proverbs 6, the ant is used as:", "options": ["Evidence in the argument", "A rhyme", "The conclusion", "The title"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 18, $j$Check 4.3: Ethos, Pathos and Logos$j$, $j${"questions": [{"q": "Ethos is an appeal to:", "options": ["Credibility", "Emotion", "Rhyme", "Logic"]}, {"q": "Pathos is an appeal to:", "options": ["Logic", "Setting", "Grammar", "Emotion"]}, {"q": "Statistics and clear reasoning are examples of:", "options": ["Mood", "Pathos", "Logos", "Ethos"]}, {"q": "Paul telling his personal story to Agrippa mainly uses:", "options": ["Alliteration only", "Exposition", "Pathos", "None"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 19, $j$Check 4.4: Reading Proverbs 15 as Wise Argument$j$, $j${"questions": [{"q": "Placing two opposite ideas side by side is:", "options": ["Antithesis (contrast)", "Setting", "Rhyme", "Plot"]}, {"q": "In Proverbs the main evidence is often:", "options": ["Shared human experience", "Maps", "Statistics tables", "Footnotes"]}, {"q": "'A soft answer turneth away wrath' is a claim about:", "options": ["Travel", "Weather", "How gentle words can calm conflict", "Money"]}, {"q": "A short, wise claim with contrast is closest to:", "options": ["A plot", "A proverb", "A footnote", "A stanza count"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 20, $j$Unit Quiz 4: Argument and Rhetoric$j$, $j${"questions": [{"q": "An argument includes:", "options": ["Only feelings", "Claim, reasons and evidence", "Only rhyme", "Only a title"]}, {"q": "Evidence plus an explanation of how it supports the claim is:", "options": ["Setting", "Plot", "Reasoning", "Mood"]}, {"q": "Ethos builds:", "options": ["Conflict", "Rhyme", "Setting", "Credibility"]}, {"q": "A rhetorical question is asked to:", "options": ["Fill space", "Make the listener think, not to get a spoken answer", "Spell", "End the speech"]}, {"q": "The best arguments:", "options": ["Use only emotion", "Ignore the audience", "Avoid evidence", "Balance ethos, pathos and logos"]}, {"q": "A rebuttal answers:", "options": ["A date", "A counterclaim", "A title", "A setting"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 21, $j$Check 5.1: Planning and Thesis$j$, $j${"questions": [{"q": "A thesis statement:", "options": ["Is a question", "Lists page numbers", "Ends every paragraph", "States the main point"]}, {"q": "Which is the stronger thesis?", "options": ["Daily reading strengthens vocabulary, focus and success in every subject.", "This essay is about reading.", "Do you read?", "Reading is a thing."]}, {"q": "Brainstorming means:", "options": ["Editing", "Copying", "Publishing", "Listing ideas without judging"]}, {"q": "In a five paragraph essay the thesis usually appears:", "options": ["Nowhere", "End of the introduction", "In the title only", "In the conclusion only"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 22, $j$Check 5.2: Drafting Paragraphs$j$, $j${"questions": [{"q": "A topic sentence:", "options": ["Is always a question", "Has no connection to the thesis", "Is the last sentence only", "States the main idea of the paragraph"]}, {"q": "'However' is a transition showing:", "options": ["Contrast", "Addition", "Example", "Order"]}, {"q": "Reasoning is:", "options": ["Explaining how evidence proves the point", "The hook", "A list of titles", "The title"]}, {"q": "A strong introduction has:", "options": ["Only a quote", "Only evidence", "Only a title", "Hook, background and thesis"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 23, $j$Check 5.3: Revising$j$, $j${"questions": [{"q": "Revising focuses on:", "options": ["Only the title", "Ideas, organization and style", "Only spelling", "Only punctuation"]}, {"q": "Which is an editing task?", "options": ["Adding a new section of evidence", "Moving a paragraph", "Rewriting the thesis", "Fixing a comma"]}, {"q": "Replacing 'a lot of people' with 'hundreds of students' is:", "options": ["Making language more specific", "Cutting", "Moving", "Editing spelling"]}, {"q": "Reading your essay aloud helps you:", "options": ["Pick a title", "Skip revising", "Catch awkward or missing words", "Count words"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 24, $j$Check 5.4: Editing and Publishing$j$, $j${"questions": [{"q": "A sentence missing a subject or verb is a:", "options": ["Thesis", "Hook", "Simile", "Fragment"]}, {"q": "Which sentence has correct agreement?", "options": ["The students read.", "The student are reading.", "The student read daily books.", "The students reads."]}, {"q": "Editing differs from revising because editing:", "options": ["Adds a section", "Chooses a topic", "Fixes conventions like spelling and punctuation", "Changes the thesis"]}, {"q": "Publishing includes:", "options": ["Skipping a final read", "Leaving off a name", "Deleting the thesis", "A title and correct formatting"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 25, $j$Unit Quiz 5: Writing Workshop$j$, $j${"questions": [{"q": "The thesis statement states:", "options": ["The main point", "The page count", "A bibliography", "The date"]}, {"q": "The writing process in order is:", "options": ["Draft, publish, plan", "Plan, draft, revise, edit, publish", "Edit, plan, draft", "Publish, edit, plan"]}, {"q": "Transitions help the reader:", "options": ["Skip paragraphs", "Move from one idea to the next", "Count words", "Find the title"]}, {"q": "Revising includes:", "options": ["Only the title", "Add, cut, move and replace", "Only spelling", "Nothing"]}, {"q": "A conclusion should:", "options": ["Restate the thesis in fresh words and leave a final thought", "Be omitted", "Introduce a new argument", "Repeat the introduction word for word"]}, {"q": "An essay's body paragraph should include:", "options": ["A topic sentence, evidence and reasoning", "Only a quotation", "Only a question", "Only a title"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 26, $j$Check 6.1: Context Clues$j$, $j${"questions": [{"q": "Context clues are found:", "options": ["Only in a dictionary", "Only in footnotes", "In the words around an unfamiliar word", "Only in titles"]}, {"q": "When the author explains the word right in the sentence, that is a:", "options": ["Setting", "Antonym clue", "Theme", "Definition clue"]}, {"q": "An antonym clue uses:", "options": ["A synonym", "An opposite word", "A date", "A rhyme"]}, {"q": "After guessing a meaning, you should:", "options": ["Memorize the page", "Delete the word", "Test it in the sentence", "Ignore it"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 27, $j$Check 6.2: Roots, Prefixes and Suffixes$j$, $j${"questions": [{"q": "The prefix 'un' means:", "options": ["Not", "Under", "Again", "Before"]}, {"q": "The root 'dict' means:", "options": ["Carry", "Speak", "Look", "Write"]}, {"q": "In 'hopeless', the suffix 'less' means:", "options": ["Without", "Between", "Full of", "Again"]}, {"q": "A manuscript is something written:", "options": ["Under water", "By hand", "Again", "Before"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 28, $j$Check 6.3: Connotation and Academic Vocabulary$j$, $j${"questions": [{"q": "Connotation is:", "options": ["The root", "The part of speech", "The feeling or association of a word", "The dictionary definition"]}, {"q": "Which word has the most positive connotation?", "options": ["Pig headed", "Bullheaded", "Stubborn", "Determined"]}, {"q": "'Infer' means to:", "options": ["Copy", "Rhyme", "Decorate", "Draw a conclusion from clues"]}, {"q": "'Evaluate' means to:", "options": ["Cut", "Retype", "Judge quality or value", "Spell"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 29, $j$Check 6.4: Clauses, Phrases, Colons and Semicolons$j$, $j${"questions": [{"q": "A clause has:", "options": ["Only a preposition", "Both a subject and a verb", "Only an adjective", "Only a noun"]}, {"q": "Which is a dependent clause?", "options": ["The students studied", "She ran home", "He sang", "Although the students studied"]}, {"q": "A semicolon can join:", "options": ["A fragment and a phrase", "A noun and a verb", "Any two words", "Two closely related independent clauses"]}, {"q": "A colon should follow:", "options": ["A preposition", "A verb", "A complete sentence", "A comma"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 30, $j$Unit Quiz 6: Vocabulary and Conventions$j$, $j${"questions": [{"q": "Context clues are:", "options": ["Hints near an unfamiliar word", "Titles", "Page numbers", "Dictionary entries"]}, {"q": "The prefix 're' means:", "options": ["Again", "Not", "Under", "Between"]}, {"q": "The root 'port' means:", "options": ["See", "Carry", "Write", "Speak"]}, {"q": "Connotation is a word's:", "options": ["Root", "Emotional association", "Spelling", "Dictionary meaning"]}, {"q": "A dependent clause:", "options": ["Always ends a sentence", "Has no verb", "Cannot stand alone", "Is a title"]}, {"q": "A semicolon can be used to:", "options": ["Replace a title", "Join two related independent clauses", "End a paragraph", "Introduce a list always"]}]}$j$::jsonb);
  insert into public.course_items (course_id, kind, position, title, content) values (cid, 'quiz', 31, $j$Final Exam: English 1$j$, $j${"questions": [{"q": "Which part of the plot is the turning point?", "options": ["Climax", "Setting", "Exposition", "Resolution"]}, {"q": "Giving a character's traits through actions is:", "options": ["Direct characterization", "Indirect characterization", "Mood", "Plot"]}, {"q": "A theme should be written as:", "options": ["A question only", "One word", "A title", "A full statement"]}, {"q": "'The Lord is my shepherd' is a:", "options": ["Metaphor", "Rhyme", "Simile", "Plot"]}, {"q": "Repeating beginning consonant sounds is:", "options": ["Alliteration", "Assonance", "Symbol", "Rhyme"]}, {"q": "A central idea is:", "options": ["The main point as a full statement", "A detail", "A topic word", "A title"]}, {"q": "An author's purpose can be to:", "options": ["Inform, persuade, entertain or express", "Only rhyme", "Only title", "Only list"]}, {"q": "A summary is written:", "options": ["Word for word", "Longer than the original", "Without main ideas", "In your own words, briefly"]}, {"q": "An argument includes:", "options": ["Only rhyme", "Only feeling", "Claim, reasons and evidence", "Only a title"]}, {"q": "Ethos appeals to:", "options": ["Logic", "Setting", "Credibility", "Emotion"]}, {"q": "A thesis statement:", "options": ["Lists sources", "Ends the essay", "Is only a question", "States the main point"]}, {"q": "Revising differs from editing because revising:", "options": ["Is the last step", "Fixes only commas", "Is skipped", "Improves ideas and organization"]}, {"q": "The prefix 'un' means:", "options": ["Again", "Not", "Before", "Between"]}, {"q": "Connotation is:", "options": ["A prefix", "A root", "A word's emotional association", "A dictionary definition"]}, {"q": "A semicolon joins:", "options": ["Two related independent clauses", "A phrase and a title", "Any two words", "A noun and a verb"]}]}$j$::jsonb);
